    #[test]
    fn test_find_first_odd() {
        let v1 = vec![2, 4, 6, 8];
        assert_eq!(find_first_odd(&v1), None);

        let v2 = vec![1, 2, 3, 4];
        assert_eq!(find_first_odd(&v2), Some(0));

        let v3 = vec![2, 4, 5, 6, 7];
        assert_eq!(find_first_odd(&v3), Some(2));

        let v4 = vec![-2, -4, -6, -7, -8];
        assert_eq!(find_first_odd(&v4), Some(3)); // -7 % 2 = -1 != 0

        let v5 = vec![0, 2, 4, 6];
        assert_eq!(find_first_odd(&v5), None);
    }
